pm.test('Kredensial tidak diizinkan untuk origin asing', () => {
          const c = pm.response.headers.get('Access-Control-Allow-Credentials') || '';
          const o = pm.response.headers.get('Access-Control-Allow-Origin') || '';
          pm.expect(o.includes('trycloudflare.com') && c === 'true').to.be.false;
        });

